a = [1, 2, 3, "python", 'java', 1, 1, 1, 2, 3]
counter = a.count(1)  #//The count() method is used to count the number of occurrences of a specified value in a list. It takes the value to be counted as an argument and returns the number of times that value appears in the list.
print(counter)  # Output: 4